private final static int _parseIndex(String str) {
    final int len = str.length();
    if (len == 0 || len > 10) {
        return -1;
    }
    if (len > 1 && str.charAt(0) == '0') {
        return -1;
    }

    int index = 0;
    for (int i = 0; i < len; ++i) {
        char c = str.charAt(i);
        if (c < '0' || c > '9') {
            return -1;
        }
        index = (index * 10) + (c - '0');
    }
    return index < 0 ? -1 : index;
}
